{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret retter spørgsmålets præmis (Udbetaling Danmark) til Uddannelses- og Forskningsstyrelsen, men det er ikke understøttet af kilderne, som nævner Udbetaling Danmark (og 'styrelsen' i XHAILe). Svaret nævner ikke, at lægeattesten kommer fra den praktiserende læge. Det tilføjer også en række indholdskrav til attesten (arbejdsopgaver, belastninger, variationer, pauser) og et afslag på det foreliggende grundlag, som ikke findes i kilderne. Svaret får ikke fat i det centrale krav om behov for fortsat behandling eller henvisning til en specialist."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Element 1 er delvist dækket: styrelsen kan bede om en lægeattest, men den praktiserende læge nævnes ikke specifikt ('egen læge eller en behandler'). Element 2 er dækket nogenlunde, fordi svaret handler om funktionelle begrænsninger. Det vigtigste er, at svaret ikke siger, at attesten skal tage stilling til behov for fortsat behandling eller henvisning til yderligere udredning eller behandling hos en specialist. Svaret nævner kun 'behandling, udvikling og forventet varighed', og det svarer ikke til henvisningselementet. Element 3 mangler derfor."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad myndigheden kan gøre ved utilstrækkelig dokumentation, og hvad lægeattesten skal beskrive."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer flere væsentlige elementer uden støtte i materialet: at Uddannelses- og Forskningsstyrelsen i stedet for Udbetaling Danmark behandler sagerne, at ansøgeren kan få en frist, og at styrelsen kan afgøre sagen på det foreliggende grundlag og give afslag. Desuden indeholder det detaljerede indholdskrav til attesten, bl.a. om hyppighed, pauser og restitution. Fristen er støttet af § 37, stk. 5, men kun hvis dokumentationen er indsendt efter stk. 3. Svaret nævner ikke denne betingelse."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger 'kan' om muligheden for at indhente supplerende oplysninger og gør ikke attesten til en automatisk pligt. Det formidler ikke et ubetinget krav om attest i alle sager. Fremmødeforbeholdet er kun påkrævet, hvis fremmøde omtales, og det gør svaret ikke."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: mulighed for at bede om oplysninger, derefter frist og afgørelse, og derefter attestens indhold med en afgrænsning af lægens og styrelsens roller. Den forkerte præmis ændrer ikke ved den interne sammenhæng."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilderne siger, at lægen 'skal' forholde sig til funktionsevnen i forhold til den ansøgte funktionsnedsættelse og redegøre for behov for behandling eller henvisning. Svaret bruger 'bør' om attestens indhold og gengiver dermed ikke kravene præcist. Det formulerer også en række ikke-kildebaserede forventninger om indholdet, som om de var retningslinjer. Brugen af 'kan' om indhentning er korrekt."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret dækker, at der kan indhentes en lægeattest, når dokumentationen ikke er tilstrækkelig, og at attesten skal beskrive funktionelle begrænsninger. Det nævner ikke den praktiserende læge specifikt og heller ikke det udtrykkelige krav om behov for fortsat behandling eller henvisning til en specialist. Det omtaler heller ikke fremmødeforbeholdet, yderligere journaloplysninger eller udgifterne, som er supplerende."
    }
  },
  "overall_notes": "Svaret er læseligt og besvarer begge dele af spørgsmålet, men det angiver ingen kilder. Det udelader det centrale krav om behandling eller henvisning til en specialist og tilføjer mange ikke-understøttede detaljer om attestens indhold og sagsbehandlingen. Det ændrer også myndigheden fra Udbetaling Danmark til Uddannelses- og Forskningsstyrelsen."
}

